record.field:
# Sync all WhatsApp channels
channels = env['meta.channel'].search([('channel_type', '=', 'whatsapp')])
for channel in channels:
    if channel.whatsapp_account_id:
        channel.whatsapp_account_id._sync_conversations_to_meta_hub()

# Send messages stuck in outgoing state
messages = env['meta.message'].search([
    ('state', '=', 'outgoing'),
    ('create_date', '>=', (datetime.datetime.now() - datetime.timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S'))
], limit=50)
for msg in messages:
    try:
        msg.action_send()
    except Exception as e:
        msg.write({'state': 'failed', 'failure_reason': str(e)})
